__device__ __forceinline__ float to_float_dev(T v) { return static_cast<float>(v); }

template <typename T>
__device__ __forceinline__ T from_float_dev(float v) { return static_cast<T>(v); }

__device__ __forceinline__ float warp_reduce_sum(float v) {
    #pragma unroll
    for (int offset = 16; offset > 0; offset >>= 1) {
        v += __shfl_down_sync(0xffffffff, v, offset);
    }
    return v;
}

template<int BLOCK_THREADS>
__device__ __forceinline__ float block_reduce_sum(float v) {
    __shared__ float shared[32];
    int lane = threadIdx.x & 31;
    int warp = threadIdx.x >> 5;
    v = warp_reduce_sum(v);
    if (lane == 0) shared[warp] = v;
    __syncthreads();
    v = (threadIdx.x < (BLOCK_THREADS + 31) / 32) ? shared[lane] : 0.0f;
    if (warp == 0) v = warp_reduce_sum(v);
    return v;
}

template <typename scalar_t, int BLOCK_THREADS>
__global__ __launch_bounds__(BLOCK_THREADS, 2)
void layernorm_kernel(const scalar_t* __restrict__ x,
                      const scalar_t* __restrict__ w,
                      const scalar_t* __restrict__ b,
                      scalar_t* __restrict__ y,
                      int64_t rows, int64_t cols, int64_t stride, float eps) {
    int64_t row = blockIdx.x;
    if (row >= rows) return;
    const scalar_t* __restrict__ xr = x + row * stride;
    scalar_t* __restrict__ yr = y + row * stride;

    float sum = 0.0f;
    for (int64_t c = threadIdx.x; c < cols; c += BLOCK_THREADS) {
        sum += to_float_dev(xr[c]);
    }
    sum = block_reduce_sum<BLOCK_THREADS>(sum);
    __shared__ float sm_mean;
    __shared__ float sm_rstd;
    if (threadIdx.x == 0) sm_mean = sum / (float)cols;
    __syncthreads();
    float mean = sm_mean;

    float varsum = 0.0f;
    for (int64_t c = threadIdx.x; c < cols; c += BLOCK_THREADS) {
        float d = to_float_dev(xr[c]) - mean;
        varsum += d * d;
    }
    varsum = block_reduce_sum<BLOCK_THREADS>(varsum);
    if (threadIdx.x == 0) sm_rstd = rsqrtf(varsum / (float)cols + eps);
    __syncthreads();
    float rstd = sm_rstd;

    for (int64_t c = threadIdx.x; c < cols; c += BLOCK_THREADS) {
        float xv = to_float_dev(xr[c]);
        float wv = to_float_dev(w[c]);
        float bv = to_float_dev(b[c]);
        float out = (xv - mean) * rstd * wv + bv;
