        yr[c]=from_f<scalar_t>((xv-mean)*rstd*to_f(w[c])+to_f(b[c]));
    }
}

template <typename scalar_t, int BT>
__global__ __launch_bounds__(BT, 2)
void ln_block_kernel(const scalar_t* __restrict__ x,const scalar_t* __restrict__ w,const scalar_t* __restrict__ b,scalar_t* __restrict__ y,
                     int64_t rows,int64_t cols,int64_t stride){
    int64_t row=blockIdx.x;
    if(row>=rows) return;
    const scalar_t* xr=x+row*stride;
    scalar_t* yr=y+row*stride;

    float sum=0.f, ss=0.f;
    for(int64_t c=threadIdx.x;c<cols;c+=BT){
        float v=to_f(xr[c]);
        sum+=v;
        ss=fmaf(v,v,ss);
    }
    block_sum2<BT>(sum,ss);

    __shared__ float sm[2];
    if(threadIdx.x==0){
        float mean=sum/(float)cols;
        sm[0]=mean;
        sm[1]=rsqrtf(fmaxf(ss/(float)cols-mean*mean,0.f)+1.0e-5f);
    }
    __syncthreads();
    float mean=sm[0], rstd=sm[1];

    for(int64_t c=threadIdx.x;c<cols;c+=BT){
        float xv=to_f(xr[c]);
        yr[c]=from_f<scalar_t>((xv-mean)*rstd*to_f(w[c])+to_f(b[c]));
    }
}

template<typename scalar_t>
void dispatch(const scalar_t* x,const scalar_t* w,const scalar_t* b,scalar_t* y,int64_t rows,int64_t cols,int64_t stride,cudaStream_t s){
    if(cols<=1024 && rows>=128){
        ln_warp_kernel<scalar_t,8><<<dim3((rows+7)/8),256,0,s>>>(x,w,b,y,rows,cols,stride);
    } else if(cols<=2048){
        ln_block_kernel<scalar_t,256><<<dim3(rows),256,0,s>>>(x,w,b,y,rows,cols,stride);
    } else {
        ln_block_kernel<scalar_t,512><<<dim3(rows),512,0,s>>>(x,w,b,y,rows,cols,stride);
    }
}

torch::Tensor layernorm_forward(torch::Tensor x, torch::Tensor w, torch::Tensor b){
    auto y=torch::empty_like(x);
    int64_t rows=x.size(0), cols=x.size(1), stride=x.stride(0);
    cudaStream_t s=at::cuda::getCurrentCUDAStream();
    AT_DISPATCH_FLOATING_TYPES_AND2(at::ScalarType::Half,at::ScalarType::BFloat16,x.scalar_type(),"ln_h100_forward",[&]{
        dispatch<scalar_t>(x.data_ptr<scalar_t>(),w.data_ptr<scalar_t>(),b.data_ptr<scalar_t>(),y.data_ptr<scalar_t>(),rows,cols,stride,s);
    });
    return y;
}

